"""Validate imported M4 results and generate the three required reports."""
from __future__ import annotations
import csv, hashlib, json
from collections import Counter
from pathlib import Path
ROOT = Path(__file__).resolve().parents[1]; NAMES = ("BONA_FIDE", "PRINT", "SCREEN")

def probability_text(row): return ", ".join(f"{name}={float(row['p_'+name]):.6f}" for name in NAMES)

def main():
    metrics = json.loads((ROOT / "artifacts/metrics/m4_texture_metrics.json").read_text(encoding="utf-8")); meta = json.loads((ROOT / "artifacts/m4/run_metadata.json").read_text(encoding="utf-8")); comparison = json.loads((ROOT / "artifacts/metrics/m4_vs_m3.json").read_text(encoding="utf-8")); m3_metrics = json.loads((ROOT / "artifacts/metrics/m3_baseline_metrics.json").read_text(encoding="utf-8"))
    m3 = {r["sample_id"]: r for r in csv.DictReader((ROOT / "artifacts/metrics/m3_test_predictions.csv").open(encoding="utf-8"))}; m4_rows = list(csv.DictReader((ROOT / "artifacts/metrics/m4_test_predictions.csv").open(encoding="utf-8"))); m4 = {r["sample_id"]: r for r in m4_rows}
    if len(m4_rows) != 44 or set(m3) != set(m4): raise RuntimeError("M3/M4 frozen-test sample IDs differ")
    if sum(sum(r) for r in metrics["confusion_matrix"]) != 44 or metrics["test_errors"] != sum(r["true_class"] != r["predicted_class"] for r in m4_rows): raise RuntimeError("M4 test count/error invariant failed")
    checkpoint = __import__("torch").load(ROOT / "artifacts/m4/best_convnext_texture.pt", map_location="cpu", weights_only=True)
    if checkpoint["manifest_sha256"] != meta["manifest_sha256"] or meta["manifest_sha256"] != json.loads((ROOT / "artifacts/m3/frozen_manifest_provenance.json").read_text())["gpu_bundle_manifest_sha256"]: raise RuntimeError("M4 checkpoint does not match frozen M3 GPU manifest")
    local_hash = hashlib.sha256((ROOT / "artifacts/data/dlc2021_protocol_a_reduced_manifest.jsonl").read_bytes()).hexdigest()
    screen_ids = [sid for sid, row in m3.items() if row["true_class"] == "SCREEN" and row["predicted_class"] == "BONA_FIDE"]; corrected = [sid for sid in screen_ids if m4[sid]["predicted_class"] == "SCREEN"]
    status_counts = Counter(r["comparison_to_m3"] for r in m4_rows)
    import matplotlib.pyplot as plt
    history = meta["history"]; epochs = [r["epoch"] for r in history]; semantic_weights = [r["branch_weights"][0] for r in history]; texture_weights = [r["branch_weights"][1] for r in history]
    figure, axis = plt.subplots(figsize=(6, 4)); axis.plot(epochs, semantic_weights, label="semantic"); axis.plot(epochs, texture_weights, label="texture")
    low, high = min(semantic_weights + texture_weights), max(semantic_weights + texture_weights); margin = max(0.001, (high-low)*0.2); axis.set_ylim(low-margin, high+margin); axis.set_xlabel("Epoch"); axis.set_ylabel("Learned fusion weight"); axis.legend(); figure.tight_layout(); figure.savefig(ROOT / "artifacts/plots/m4_branch_weights.png", dpi=160); plt.close(figure)
    delta = comparison["delta_m4_minus_m3"]
    report = ["# M4 ConvNeXt + Texture Report", "", "These are our observed results on the frozen 300-sample Protocol A-Reduced experiment, not results from the original paper or the full DLC-2021 corpus.", "", "## Controlled protocol", "", f"- Frozen manifest: 300 samples; local SHA-256 `{local_hash}`; portable GPU SHA-256 `{meta['manifest_sha256']}` (identical to M3 GPU provenance).", "- Splits, crop geometry, labels, seed, normalization, class weights, and no-stochastic-augmentation policy are identical to M3.", "- The checkpoint was selected only by validation macro-F1. The frozen 44-sample test set was instantiated after checkpoint selection and evaluated once.", "", "## Architecture and training", "", f"- ImageNet-pretrained `{meta['model_name']}` semantic branch; stem/stages 0-2 frozen, stage 3 and final normalization trainable.", "- Pixel-only texture branch: adaptive 32x32 pooling, Conv-BN-ReLU widths 16/32/64, global pooling, 64-D output.", "- Both branches project to 256-D and combine through two softmax-normalized learned scalar weights; progressive classifier 256->512->256->128->3.", f"- Parameters: {meta['parameters']['total']:,} total; {meta['parameters']['trainable']:,} trainable; {meta['parameters']['frozen']:,} frozen.", f"- GPU: {meta['device_name']}; physical batch {meta['config']['batch_size']}; accumulation {meta['config']['accumulation']}; duration {meta['duration_seconds']:.2f} s; {meta['epochs_completed']} epochs; best epoch {meta['best_epoch']}.", "", "## Observed results", "", f"- Best validation macro-F1: {metrics['best_validation_macro_f1']:.6f}.", f"- Test accuracy: {metrics['accuracy']:.6f}; macro precision: {metrics['macro_precision']:.6f}; macro recall: {metrics['macro_recall']:.6f}; macro-F1: {metrics['macro_f1']:.6f}.", *[f"- {name}: precision {metrics['per_class_precision'][i]:.6f}; recall {metrics['per_class_recall'][i]:.6f}; F1 {metrics['per_class_f1'][i]:.6f}." for i,name in enumerate(NAMES)], f"- Confusion matrix (rows true, columns predicted; BONA_FIDE, PRINT, SCREEN): `{metrics['confusion_matrix']}`.", f"- Failures: {metrics['test_errors']} of 44.", "", "## Delta versus immutable M3", "", f"- Accuracy: {delta['accuracy']:+.6f}; macro-F1: {delta['macro_f1']:+.6f}.", *[f"- {name} F1: {delta['per_class_f1'][name]:+.6f}." for name in NAMES], f"- Four of the six M3 SCREEN->BONA_FIDE errors were corrected; two persisted. SCREEN F1 was unchanged because other SCREEN errors and prediction tradeoffs offset those corrections.", "", "## Learned fusion weights", "", f"- Best-checkpoint semantic weight: {metrics['learned_fusion_weights']['semantic']:.6f}.", f"- Best-checkpoint texture weight: {metrics['learned_fusion_weights']['texture']:.6f}.", "", "These are learned fusion weights, not proof of causal importance.", "", "## Padding diagnostic", "", f"- Padded: {metrics['padding_diagnostic']['true']['errors']}/{metrics['padding_diagnostic']['true']['count']} errors ({metrics['padding_diagnostic']['true']['error_rate']:.2%}); M3 was {m3_metrics['padding_diagnostic']['true']['error_rate']:.2%}.", f"- Non-padded: {metrics['padding_diagnostic']['false']['errors']}/{metrics['padding_diagnostic']['false']['count']} errors ({metrics['padding_diagnostic']['false']['error_rate']:.2%}); M3 was {m3_metrics['padding_diagnostic']['false']['error_rate']:.2%}.", "", "Class x padding counts are stored in the metrics artifact. These small descriptive strata do not establish that padding caused any prediction.", "", "## Limitations", "", "- The test set has only 44 samples and this is one seed, so deltas have high sampling uncertainty.", "- This experiment changes more than a single feature extractor relative to M3: it introduces projections and a deeper classifier alongside the texture branch. It tests the approved ConvNeXt+Texture system, not the isolated causal contribution of texture alone.", "- The reduced acquisition is not the full DLC-2021 benchmark; no paper-level reproduction claim is justified.", "- Learned fusion weights and embedding norms are descriptive and are not causal importance measures.", "", "## Proposed M5 plan (not implemented)", "", "With explicit approval, M5 should run one controlled ConvNeXt+Edge experiment on the same frozen protocol: implement a pixel-only 32-D fixed-gradient/lightweight edge branch, retain the M3 semantic freeze policy, independently project semantic and edge features to 256-D, use two softmax-normalized learned weights and the same progressive classifier, repeat the CPU gradient/checkpoint smoke gate, then run exactly one validation-selected T4 experiment and one frozen-test evaluation. Report M5 vs M3 and class/padding/failure diagnostics. Do not add texture+edge three-branch fusion until a later separately approved milestone."]
    (ROOT / "docs/M4_TEXTURE_REPORT.md").write_text("\n".join(report)+"\n", encoding="utf-8")
    screen = ["# M4 SCREEN Error Comparison", "", "The six rows below are exactly the M3 SCREEN->BONA_FIDE errors. Probabilities follow BONA_FIDE, PRINT, SCREEN.", ""]
    for sid in screen_ids:
        a,b=m3[sid],m4[sid]; state="CORRECTED" if b["predicted_class"]=="SCREEN" else "PRESERVED" if b["predicted_class"]=="BONA_FIDE" else "CHANGED TO ANOTHER WRONG CLASS"
        screen += [f"## `{sid}`", "", f"- M3: `{a['predicted_class']}`; {probability_text(a)}.", f"- M4: `{b['predicted_class']}`; {probability_text(b)}.", f"- Outcome: **{state}**.", ""]
    screen += [f"Summary: {len(corrected)}/6 corrected, {6-len(corrected)}/6 preserved, 0/6 changed to another wrong class.", ""]
    (ROOT / "docs/M4_SCREEN_ERROR_COMPARISON.md").write_text("\n".join(screen), encoding="utf-8")
    failures = ["# M4 Failure Analysis", "", f"Observed M4 failures: {metrics['test_errors']} of 44. Among test samples: {status_counts['NEW_FAILURE']} new failures, {status_counts['PERSISTENT_FAILURE']} persistent failures, and {status_counts['CORRECTED_M3_FAILURE']} corrected M3 failures. Labels are comparisons, not causal explanations.", ""]
    for row in m4_rows:
        if row["true_class"] == row["predicted_class"]: continue
        failures += [f"## `{row['sample_id']}`", "", f"- Observed: `{row['true_class']}` -> `{row['predicted_class']}`; confidence {float(row['confidence']):.6f}; `{row['comparison_to_m3']}`.", f"- Probabilities: {probability_text(row)}.", f"- Padding: `{row['padded']}`; crop: `{row['crop_path']}`.", "- Possible explanation: not assigned automatically; visual interpretation would be speculative.", ""]
    (ROOT / "docs/M4_FAILURE_ANALYSIS.md").write_text("\n".join(failures), encoding="utf-8")
    print(json.dumps({"screen_corrected":len(corrected),"status_counts":status_counts,"local_manifest_sha256":local_hash},default=dict,indent=2)); return 0
if __name__ == "__main__": raise SystemExit(main())
